function compute(s) {
  const n = Math.max(1, Math.round(s.n));
  const m = Math.max(1, Math.round(s.m));
  const dk = Math.max(1, Math.round(s.dk));
  const dv = Math.max(1, Math.round(s.dv));
  const scale = !!s.scale;

  const Q = L.copy(s.Q);
  const K = L.copy(s.K);
  const V = L.copy(s.V);

  const sqrtDk = Math.sqrt(dk);
  const factor = scale ? 1 / sqrtDk : 1;

  // raw scores S = Q K^T
  const raw = L.matmul(Q, L.transpose(K));
  const S = L.mapM(raw, (x) => x * factor);

  // softmax along each row
  const A = S.map((row) => L.softmax(row));

  // output O = A V
  const O = L.matmul(A, V);

  const rowSums = A.map((row) => L.sum(row));
  const maxScores = S.map((row) => L.max(row));
  const minScores = S.map((row) => L.min(row));
  const maxWeights = A.map((row) => L.max(row));

  // explicit weighted sum of V, for the invariant check
  const Ocheck = A.map((row) => {
    const acc = L.zeros(dv);
    for (let j = 0; j < m; j++) {
      for (let c = 0; c < dv; c++) acc[c] += row[j] * V[j][c];
    }
    return acc;
  });

  let maxOutputDiff = 0;
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < dv; c++) {
      maxOutputDiff = Math.max(maxOutputDiff, Math.abs(O[i][c] - Ocheck[i][c]));
    }
  }

  let minWeight = Infinity;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) minWeight = Math.min(minWeight, A[i][j]);
  }
  if (!isFinite(minWeight)) minWeight = 0;

  let maxRowSumErr = 0;
  for (let i = 0; i < n; i++) maxRowSumErr = Math.max(maxRowSumErr, Math.abs(rowSums[i] - 1));

  return {
    n, m, dk, dv, scale, sqrtDk, factor,
    Q, K, V,
    raw, S, A, O, Ocheck,
    rowSums, maxScores, minScores, maxWeights,
    maxOutputDiff, minWeight, maxRowSumErr
  };
}

function render(s, r) {
  const W = 760, H = 470;
  const parts = [];

  const n = r.n, m = r.m, dk = r.dk, dv = r.dv;

  // ---------- left: score matrix ----------
  const lx = 20, ly = 70, lw = 250, lh = 170;
  const scoreTitle = r.scale
    ? "scores  S = QK\u1D40 / \u221Ad\u2096"
    : "scores  S = QK\u1D40  (unscaled)";

  let sMin = 0, sMax = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      sMin = Math.min(sMin, r.S[i][j]);
      sMax = Math.max(sMax, r.S[i][j]);
    }
  }
  if (sMax - sMin < 1e-12) { sMax = sMin + 1; }

  parts.push(L.heatmap({
    x: lx, y: ly, w: lw, h: lh,
    matrix: r.S,
    rowLabels: L.range(n).map((i) => "q" + (i + 1)),
    colLabels: L.range(m).map((j) => "k" + (j + 1)),
    title: scoreTitle,
    min: sMin, max: sMax,
    fmt: (v) => L.fmt(v, 2)
  }));

  // softmax arrows
  const arrowY = ly + lh + 26;
  for (let i = 0; i < n; i++) {
    const y = ly + (i + 0.5) * (lh / n);
    parts.push(L.arrow(lx + lw + 6, y, lx + lw + 44, arrowY + 4, { color: L.color(i), width: 1.5 }));
  }
  parts.push(L.text(lx + lw + 25, arrowY + 22, "softmax per row", { size: 12, anchor: "middle", color: "#444" }));

  // ---------- right: weights + output ----------
  const rx = 350, ry = 70, rw = 250, rh = 170;

  parts.push(L.heatmap({
    x: rx, y: ry, w: rw, h: rh,
    matrix: r.A,
    rowLabels: L.range(n).map((i) => "q" + (i + 1)),
    colLabels: L.range(m).map((j) => "k" + (j + 1)),
    title: "attention weights  A = softmax(S)",
    min: 0, max: 1,
    fmt: (v) => L.fmt(v, 2)
  }));

  // row-sum readouts
  for (let i = 0; i < n; i++) {
    const y = ry + (i + 0.5) * (rh / n);
    parts.push(L.text(rx + rw + 8, y, "\u03A3 = " + L.fmt(r.rowSums[i], 3), {
      size: 12, anchor: "start", color: L.color(i), weight: "bold"
    }));
  }

  // output bars
  const ox = 350, oy = 300, ow = 380, oh = 140;
  const barVals = [];
  const barLabels = [];
  const barColors = [];
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < dv; c++) {
      barVals.push(r.O[i][c]);
      barLabels.push("q" + (i + 1) + "\u00B7" + (c + 1));
      barColors.push(L.color(i));
    }
  }
  let oMin = 0, oMax = 0;
  for (const v of barVals) { oMin = Math.min(oMin, v); oMax = Math.max(oMax, v); }
  if (oMax - oMin < 1e-12) { oMax = oMin + 1; }

  parts.push(L.bars({
    x: ox, y: oy, w: ow, h: oh,
    values: barVals,
    labels: barLabels,
    title: "output  O = A V   (one group per query)",
    yLabel: "value",
    min: oMin, max: oMax,
    colors: barColors,
    fmt: (v) => L.fmt(v, 2)
  }));

  // header
  parts.push(L.text(20, 24, "Scaled dot-product attention", { size: 16, weight: "bold", anchor: "start" }));
  parts.push(L.text(20, 44,
    "n=" + n + "  m=" + m + "  d\u2096=" + dk + "  d\u1D65=" + dv +
    "   scaling " + (r.scale ? "ON  (1/\u221A" + dk + " = " + L.fmt(r.factor, 3) + ")" : "OFF"),
    { size: 12, anchor: "start", color: "#555" }));

  return L.svg(W, H, parts.join(""));
}

function show(s, r) {
  const out = [];

  out.push({
    label: "Q (queries)",
    value: r.Q,
    rowLabels: L.range(r.n).map((i) => "q" + (i + 1)),
    colLabels: L.range(r.dk).map((c) => "d" + (c + 1)),
    highlight: []
  });
  out.push({
    label: "K (keys)",
    value: r.K,
    rowLabels: L.range(r.m).map((j) => "k" + (j + 1)),
    colLabels: L.range(r.dk).map((c) => "d" + (c + 1)),
    highlight: []
  });
  out.push({
    label: "V (values)",
    value: r.V,
    rowLabels: L.range(r.m).map((j) => "v" + (j + 1)),
    colLabels: L.range(r.dv).map((c) => "d" + (c + 1)),
    highlight: []
  });

  out.push({
    label: "raw scores  QK\u1D40",
    value: r.raw,
    digits: 3,
    rowLabels: L.range(r.n).map((i) => "q" + (i + 1)),
    colLabels: L.range(r.m).map((j) => "k" + (j + 1)),
    highlight: []
  });

  out.push({
    label: "scaled scores  S = QK\u1D40/\u221Ad\u2096",
    value: r.S,
    digits: 3,
    note: r.scale ? "divided by \u221A" + r.dk + " = " + L.fmt(r.sqrtDk, 3) : "scaling off: S = QK\u1D40",
    rowLabels: L.range(r.n).map((i) => "q" + (i + 1)),
    colLabels: L.range(r.m).map((j) => "k" + (j + 1)),
    highlight: []
  });

  out.push({
    label: "attention weights  A = softmax(S)",
    value: r.A,
    digits: 3,
    note: "each row sums to 1",
    rowLabels: L.range(r.n).map((i) => "q" + (i + 1)),
    colLabels: L.range(r.m).map((j) => "k" + (j + 1)),
    highlight: []
  });

  out.push({
    label: "row sums of A",
    value: r.rowSums,
    digits: 6,
    note: "must equal 1 for every query",
    colLabels: L.range(r.n).map((i) => "q" + (i + 1)),
    highlight: []
  });

  out.push({
    label: "output  O = A V",
    value: r.O,
    digits: 3,
    note: "weighted sum of the value rows",
    rowLabels: L.range(r.n).map((i) => "q" + (i + 1)),
    colLabels: L.range(r.dv).map((c) => "d" + (c + 1)),
    highlight: []
  });

  out.push({
    label: "max |O \u2212 explicit weighted sum of V|",
    value: r.maxOutputDiff,
    digits: 9,
    note: "should be 0 up to floating point"
  });

  out.push({
    label: "smallest attention weight",
    value: r.minWeight,
    digits: 6,
    note: "softmax outputs are never negative"
  });

  return out;
}

function checks(s, r) {
  const res = [];

  res.push({
    name: "every row of A sums to 1",
    pass: r.maxRowSumErr < 1e-9,
    detail: "max |row sum \u2212 1| = " + L.fmt(r.maxRowSumErr, 12)
  });

  res.push({
    name: "O equals the explicit weighted sum of V",
    pass: r.maxOutputDiff < 1e-9,
    detail: "max |O \u2212 \u03A3\u2c7c A\u1d62\u2c7c v\u2c7c| = " + L.fmt(r.maxOutputDiff, 12)
  });

  res.push({
    name: "all attention weights are non-negative",
    pass: r.minWeight >= 0,
    detail: "smallest weight = " + L.fmt(r.minWeight, 9)
  });

  const expectedFactor = r.scale ? 1 / Math.sqrt(r.dk) : 1;
  let scaleErr = 0;
  for (let i = 0; i < r.n; i++) {
    for (let j = 0; j < r.m; j++) {
      scaleErr = Math.max(scaleErr, Math.abs(r.S[i][j] - r.raw[i][j] * expectedFactor));
    }
  }
  res.push({
    name: r.scale ? "S = QK\u1D40 / \u221Ad\u2096" : "scaling off: S = QK\u1D40",
    pass: scaleErr < 1e-9,
    detail: "max |S \u2212 QK\u1D40 \u00B7 factor| = " + L.fmt(scaleErr, 12) +
      "  (factor = " + L.fmt(expectedFactor, 6) + ")"
  });

  let finite = true;
  for (let i = 0; i < r.n; i++) {
    for (let c = 0; c < r.dv; c++) {
      if (!isFinite(r.O[i][c])) finite = false;
    }
  }
  res.push({
    name: "output contains no NaN or Infinity",
    pass: finite,
    detail: finite ? "all " + (r.n * r.dv) + " output entries are finite" : "found a non-finite output entry"
  });

  return res;
}
